@Bean
@Order(1)
public SecurityFilterChain apiSecurityFilterChain(HttpSecurity http) throws Exception {
    String viewRole = properties.viewRole();
    http.securityMatcher("/api/**")
        .authorizeHttpRequests(auth -> auth
            .requestMatchers(HttpMethod.GET, "/api/**").hasAnyRole("SVC_READ", viewRole)
            .anyRequest().authenticated())
        .oauth2ResourceServer(rs -> rs.jwt(jwt -> jwt.jwtAuthenticationConverter(jwtAuthenticationConverter())))
        .sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
        .csrf(csrf -> csrf.disable());
    return http.build();
}

/** Maps the "roles" claim of a bearer token (service accounts) to ROLE_* authorities. */
@Bean
public JwtAuthenticationConverter jwtAuthenticationConverter() {
    JwtAuthenticationConverter converter = new JwtAuthenticationConverter();
    converter.setJwtGrantedAuthoritiesConverter(jwt -> new HashSet<>(KeycloakRoles.fromClaims(jwt.getClaims())));
    converter.setPrincipalClaimName("preferred_username");
    return converter;
}

@PostMapping("/accounting-events")
@PreAuthorize("hasAnyRole('SVC_GL_POST', 'GL_MANAGE')")
public ResponseEntity<AccountingEventResult> post(@Valid @RequestBody AccountingEventRequest request) {
    AccountingEventResult result = eventService.process(request);
    return ResponseEntity.status(result.duplicate() ? HttpStatus.OK : HttpStatus.CREATED).body(result);
}
